// LaunchURL opens a web browser or in-app view to a given `url`.
func (c *UrlLauncher) LaunchURL(url any, opts ...LaunchURLOptions) error {
	m := map[string]any{}
	m["url"] = encodeArg(url)
	if len(opts) > 0 {
		o := opts[0]
		setIf(m, "mode", o.Mode)
		if o.WebViewConfiguration != nil {
			m["web_view_configuration"] = o.WebViewConfiguration.toMap()
		}
		if o.BrowserConfiguration != nil {
			m["browser_configuration"] = o.BrowserConfiguration.toMap()
		}
		setIf(m, "web_only_window_name", o.WebOnlyWindowName)
	}
	_, err := c.invoke("launch_url", m)
	return err
}

// CanLaunchURL checks whether the specified URL can be handled by some app installed on
// the device.
func (c *UrlLauncher) CanLaunchURL(url any) (bool, error) {
	m := map[string]any{}
	m["url"] = encodeArg(url)
	return invokeResult[bool](&c.controlBase, "can_launch_url", m)
}

// CloseInAppWebView closes the in-app web view if it is currently open.
func (c *UrlLauncher) CloseInAppWebView() error {
	_, err := c.invoke("close_in_app_web_view", nil)
	return err
}

// OpenWindow opens a popup browser window in web environments.
func (c *UrlLauncher) OpenWindow(url any, opts ...OpenWindowOptions) error {
	m := map[string]any{}
	m["url"] = encodeArg(url)
	if len(opts) > 0 {
		o := opts[0]
		setIf(m, "title", o.Title)
		setIf(m, "width", o.Width)
		setIf(m, "height", o.Height)
	}
	_, err := c.invoke("open_window", m)
	return err
}

// SupportsLaunchMode checks whether the specified launch mode is supported.
func (c *UrlLauncher) SupportsLaunchMode(mode LaunchMode) (bool, error) {
	m := map[string]any{}
	m["mode"] = encodeArg(mode)
	return invokeResult[bool](&c.controlBase, "supports_launch_mode", m)
}

